
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_apbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_apbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.456176034453826e+01, 9.090100231292655e+01, 8.589488987096931e+01, 7.919825875781738e+01, 7.051826393904530e+01, 5.976169037849902e+01, 4.725319307403724e+01, 3.394836104180417e+01, 2.143274580022678e+01, 1.143915248820425e+01, 5.056640365642587e+00, 2.544742979034910e+00, 1.915332823901233e+00, 1.276127531214528e+00, 6.469494529762472e-01, 2.426974621441198e-01, 6.063124762051914e-02, 7.454641928409634e-03, 3.450496880083853e-04, 4.328963196222450e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


